from abc import ABC, abstractmethod
from typing import Any

DISCLAIMER_TEXT = (
    "DISCLAIMER: This guidance is generated by an automated AI assistant for educational and "
    "informational purposes only. It does NOT constitute a confirmed medical diagnosis, clinical "
    "prescription, or emergency medical advice. Always consult a licensed healthcare professional "
    "or visit the nearest emergency facility for critical or urgent symptoms."
)


class BaseAIProvider(ABC):
    """
    Abstract interface for AI healthcare assistance providers.
    Decouples business logic from external LLM vendors (Google Gemini, OpenAI, Mock, etc.).
    """

    @abstractmethod
    def generate_guidance(self, query: str, context: dict[str, Any] | None = None) -> dict[str, Any]:
        """
        Processes general health or symptom inquiry and returns structured guidance
        along with an mandatory medical disclaimer.
        """
        pass

    @abstractmethod
    def summarize_medical_record(
        self,
        title: str,
        description: str,
        clinical_data: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """
        Summarizes authorized clinical notes into clear, patient-friendly bullet points.
        """
        pass
